Ltac fsetdec :=
  unfold iff in *; fold any not; intros;
   FSetDecideAuxiliary.abstract_elements;
   FSetDecideAuxiliary.no_logical_interdep; decompose records;
   FSetDecideAuxiliary.discard_nonFSet;
   unfold AtomSetImpl.Empty, AtomSetImpl.Subset, AtomSetImpl.Equal in *;
   intros; FSetDecideAuxiliary.change_to_E_t;
   FSetDecideAuxiliary.E_eq_to_Logic_eq; subst ++;
   FSetDecideAuxiliary.Logic_eq_to_E_eq; pull not using FSet_decidability;
   unfold not in *;
   match goal with
   | H:?x `in` ?r -> False
     |- ?x `in` ?s -> False => contradict H; FSetDecideAuxiliary.fsetdec_body
   | H:?x `in` ?r -> False
     |- ?x = ?y -> False => contradict H; FSetDecideAuxiliary.fsetdec_body
   | H:?x `in` ?r -> False
     |- ?y = ?x -> False => contradict H; FSetDecideAuxiliary.fsetdec_body
   | H:?P -> False
     |- ?Q -> False =>
         tryif
          prop (FSetDecideAuxiliary.FSet_elt_Prop P) holds by
            auto  100 with FSet_Prop
           then
          (contradict H; FSetDecideAuxiliary.fsetdec_body) else
          FSetDecideAuxiliary.fsetdec_body 
   | |- _ => FSetDecideAuxiliary.fsetdec_body
   end

